def fitform(f,npar,starts=60,seed=0):
    rng=np.random.default_rng(seed)
    best=(np.inf,None)
    def res(p):
        with np.errstate(all='ignore'):
            r=f(p)-dA_dt
        r=np.where(np.isfinite(r),r,1e3)
        return r
    for s in range(starts):
        p0=rng.normal(0,1,npar)
        try:
            o=so.least_squares(res,p0,method='lm' if False else 'trf',max_nfev=2000)
            e=np.mean(o.fun**2)/var
            if e<best[0]: best=(e,o.x)
        except Exception: pass
    return best
